/* ---------- Log in link in the main menu + email-link landing ---------- */
  function setAuthNav() {
    const a = $("#tt-login"); if (!a) return;
    if (user) {
      a.textContent = "Log out"; a.href = "#";
      a.onclick = async (e) => { e.preventDefault(); try { await loadSB(); await sb.auth.signOut(); } catch (x) {} user = null; setAuthNav(); if (famRoute()) render(); };
    } else {
      a.textContent = "Log in"; a.href = "#fam-login";
      a.onclick = () => { const h = location.hash || ""; sessionStorage.setItem("fam-next", h && !/^#fam-/.test(h) ? h : "#"); };
    }
  }
  function addLoginNav() {
    const nav = $("nav.main"); if (!nav || $("#tt-login")) return;
    const a = document.createElement("a"); a.id = "tt-login"; a.href = "#fam-login"; a.textContent = "Log in";
    const donate = nav.querySelector('a[href="#donate"]'); donate ? donate.before(a) : nav.appendChild(a);
    setAuthNav();
    try { if (Object.keys(localStorage).some((k) => /^sb-.*-auth-token$/.test(k))) loadSB().then(setAuthNav, () => {}); } catch (e) {}
  }
  function toLogin(msg) {
    sessionStorage.setItem("fam-msg", msg);
    try { history.replaceState(null, "", location.pathname + "#fam-login"); } catch (e) { location.hash = "fam-login"; }
  }
  function authLanding() {
    const p = new URLSearchParams(location.search.replace(/^\?/, "") + "&" + (location.hash || "").replace(/^#/, ""));
    const code = p.get("error_code"), desc = p.get("error_description");
    if (!code && !desc) return;
    if (code === "otp_expired") toLogin("That email link has expired or was already used. If you clicked it once already, your account is probably confirmed, so try logging in below. If not, type your email and press “Resend confirmation email”.");
    else toLogin((desc || "Something went wrong with that email link.") + ". Please try logging in below.");
  }
  function codeLanding() {
    if (!/[?&]code=/.test(location.search)) return;
    loadSB().then(() => setTimeout(() => {
      if (user || !/[?&]code=/.test(location.search)) return;
      toLogin("Your email is confirmed. Please log in below. (The link was opened in a different browser than the one you signed up in, so we couldn't sign you in automatically.)");
      render();
    }, 1500)).catch(() => {});
  }

